import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        int[] last = new int[101];
        int[] total = new int[101];
        boolean[] seen = new boolean[101];
        Arrays.fill(last, -1);

        int tempo = 0;
        boolean hasEvent = false;

        for (int i = 0; i < N; i++) {
            char c = sc.next().charAt(0);
            int x = sc.nextInt();

            if (c == 'T') {
                if (hasEvent) {
                    tempo += x - 1;
                }
            } else {
                seen[x] = true;
                if (c == 'R') {
                    last[x] = tempo;
                } else {
                    if (last[x] != -1) {
                        total[x] += tempo - last[x];
                        last[x] = -1;
                    }
                }
                hasEvent = true;
                tempo += 1;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 100; i++) {
            if (seen[i]) {
                if (last[i] != -1) {
                    sb.append(i).append(" -1\n");
                } else {
                    sb.append(i).append(' ').append(total[i]).append('\n');
                }
            }
        }

        System.out.print(sb);
    }
}
